import type { DetailedRecipe, IngredientUnit, Recipe } from '../types/recipe';

type IngredientSeed = [name: string, quantity: number, unit: IngredientUnit, note?: string];
type StepSeed = [title: string, description: string, durationMinutes?: number];
type Seed = Omit<Recipe, 'id' | 'image' | 'servings' | 'ingredients' | 'utensils' | 'preparationSteps'> & {
  servings: number;
  ingredients: IngredientSeed[];
  utensils: string[];
  preparationSteps: StepSeed[];
};

function recipe(seed: Seed): DetailedRecipe {
  return {
    ...seed,
    id: `ecp-${seed.slug}`,
    image: { src: `/images/recipes/${seed.category}/${seed.slug}.webp`, alt: `${seed.title}` },
    ingredients: seed.ingredients.map(([name, quantity, unit, note], index) => ({
      id: `${seed.slug}-ingredient-${index + 1}`, name, quantity, unit, ...(note ? { note } : {}),
    })),
    utensils: seed.utensils.map((name, index) => ({ id: `${seed.slug}-utensil-${index + 1}`, name })),
    preparationSteps: seed.preparationSteps.map(([title, description, durationMinutes], index) => ({
      order: index + 1, title, description, ...(durationMinutes ? { durationMinutes } : {}),
    })),
  };
}

