/** Índice por slug para búsquedas y resolución de relaciones. */
export const RECIPES_BY_SLUG: Record<string, DetailedRecipe> = Object.fromEntries(
  RECIPES.map((item) => [item.slug, item]),
);

/** Conteo dinámico de recetas por categoría. */
export const RECIPE_COUNT_BY_CATEGORY: Record<string, number> = RECIPES.reduce(
  (counts, item) => {
    counts[item.category] = (counts[item.category] ?? 0) + 1;
    return counts;
  },
  {} as Record<string, number>,
);
